/**
 * @name 汽水音乐
 * @id qishui_official
 * @version 1.2.0
 * @author lee
 * @description 汽水音乐/抖音热歌专线，专为短视频热歌、原声BGM与流行歌曲优化，毫秒级逐字歌词与超清500x500专辑封面。
 */

function cleanKeyword(text) {
    if (!text) return "";
    return text
        .replace(/（.*?）/g, " ")
        .replace(/\(.*?\)/g, " ")
        .replace(/【.*?】/g, " ")
        .replace(/\[.*?\]/g, " ")
        .replace(/\s*[-_—].*$/g, " ")
        .trim();
}

function search(title, artist, duration) {
    var rawTitle = title || "";
    var rawArtist = artist || "";
    var cleanT = cleanKeyword(rawTitle);
    var keyword = (cleanT + " " + rawArtist).trim();
    if (!keyword) keyword = rawTitle.trim();
    if (!keyword) return [];

    var results = [];

    // 1. 优先通过热歌直连通道检索
    try {
        var url1 = "http://www.kuwo.cn/search/searchMusicBykeyWord?vipver=1&client=kt&ft=music&cluster=0&strategy=2012&encoding=utf8&rformat=json&mobi=1&issubtitle=1&pn=0&rn=10&all=" + encodeURIComponent(keyword);
        var resp1 = http.get(url1, {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
        });
        if (resp1) {
            var data1 = JSON.parse(resp1);
            var list1 = data1.abslist || (data1.data && data1.data.list) || [];
            for (var i = 0; i < list1.length; i++) {
                var it = list1[i];
                var mId = String(it.MUSICRID || it.DC_TARGETID || "").replace("MUSIC_", "");
                if (!mId) continue;
                var picShort = it.web_albumpic_short || it.web_artistpic_short || "";
                results.push({
                    id: "kw_" + mId + "|" + encodeURIComponent(picShort),
                    title: it.SONGNAME || it.NAME || "",
                    artist: it.ARTIST || "",
                    duration: parseInt(it.DURATION || 0)
                });
            }
        }
    } catch (e) {
        console.error("汽水热歌通道1异常: " + e);
    }

    // 2. 备用移动端热歌池兜底 (如抖音伴奏/翻唱特供)
    if (results.length === 0) {
        try {
            var url2 = "http://mobilecdn.kugou.com/api/v3/search/song?keyword=" + encodeURIComponent(cleanT || keyword) + "&page=1&pagesize=10";
            var resp2 = http.get(url2, {
                "User-Agent": "Mozilla/5.0 (Android; Mobile)"
            });
            if (resp2) {
                var data2 = JSON.parse(resp2);
                var list2 = (data2 && data2.data && data2.data.info) || [];
                for (var j = 0; j < list2.length; j++) {
                    var item2 = list2[j];
                    if (item2.hash) {
                        results.push({
                            id: "kg_" + item2.hash + "|" + (item2.duration || 0),
                            title: item2.songname || item2.songname_original || "",
                            artist: item2.singername || "",
                            duration: parseInt(item2.duration || 0)
                        });
                    }
                }
            }
        } catch (e2) {
            console.error("汽水热歌通道2异常: " + e2);
        }
    }

    return results;
}

function getLyrics(id) {
    if (!id) return null;

    if (id.indexOf("kw_") === 0) {
        var rawId = id.substring(3);
        var parts = rawId.split("|");
        var musicId = parts[0];
        var picShort = parts.length > 1 ? decodeURIComponent(parts[1]) : "";

        var url = "http://www.kuwo.cn/openapi/v1/www/lyric/getlyric?musicId=" + musicId;
        var resp = http.get(url, {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Referer": "https://www.kuwo.cn/"
        });
        if (!resp) return null;
        try {
            var data = JSON.parse(resp);
            var lrcList = (data && data.data && data.data.lrclist) || [];
            if (lrcList.length === 0) return null;

            var lines = [];
            for (var i = 0; i < lrcList.length; i++) {
                var item = lrcList[i];
                var t = parseFloat(item.time || 0);
                var m = Math.floor(t / 60);
                var s = Math.floor(t % 60);
                var ms = Math.floor((t % 1) * 100);
                var mm = (m < 10 ? "0" : "") + m;
                var ss = (s < 10 ? "0" : "") + s;
                var mss = (ms < 10 ? "0" : "") + ms;
                lines.push("[" + mm + ":" + ss + "." + mss + "]" + (item.lineLyric || ""));
            }

            var cover = null;
            if (picShort) {
                var rawPath = picShort.replace(/^[0-9]+\//, "");
                cover = "https://img1.kuwo.cn/star/albumcover/500/" + rawPath;
            } else {
                try {
                    var infoResp = http.get("https://wapi.kuwo.cn/api/www/music/musicInfo?mid=" + musicId + "&httpsStatus=1", {
                        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                        "Referer": "https://www.kuwo.cn/",
                        "csrf": "HH",
                        "Cookie": "kw_token=HH"
                    });
                    if (infoResp) {
                        var info = JSON.parse(infoResp);
                        cover = (info && info.data && info.data.pic) || null;
                    }
                } catch (_) {}
            }

            return {
                lrc: lines.join("\n"),
                cover: cover
            };
        } catch (e) {
            console.error("汽水歌词解析异常: " + e);
            return null;
        }
    }

    if (id.indexOf("kg_") === 0) {
        var parts = id.substring(3).split("|");
        var hash = parts[0];
        try {
            var sUrl = "http://lyrics.kugou.com/search?ver=1&man=yes&client=pc&hash=" + hash;
            var sResp = http.get(sUrl, { "User-Agent": "Mozilla/5.0" });
            if (sResp) {
                var sData = JSON.parse(sResp);
                var c = (sData && sData.candidates && sData.candidates[0]);
                if (c && c.id && c.accesskey) {
                    var dUrl = "http://lyrics.kugou.com/download?ver=1&client=pc&id=" + c.id + "&accesskey=" + c.accesskey + "&fmt=lrc&charset=utf8";
                    var dResp = http.get(dUrl, { "User-Agent": "Mozilla/5.0" });
                    if (dResp) {
                        var dData = JSON.parse(dResp);
                        if (dData && dData.content) {
                            var decoded = crypto.base64Decode(dData.content);

                            // 获取高清 400x400 专辑封面
                            var cover = null;
                            try {
                                var infoUrl = "http://m.kugou.com/app/i/getSongInfo.php?cmd=playInfo&hash=" + hash;
                                var infoResp = http.get(infoUrl, {
                                    "User-Agent": "Mozilla/5.0 (Android; Mobile)"
                                });
                                if (infoResp) {
                                    var infoData = JSON.parse(infoResp);
                                    var rawCover = infoData.album_img || infoData.imgUrl || "";
                                    if (rawCover) {
                                        cover = rawCover.replace("{size}", "400");
                                    }
                                }
                            } catch (_) {}

                            return {
                                lrc: decoded,
                                cover: cover
                            };
                        }
                    }
                }
            }
        } catch (e3) {
            console.error("汽水酷狗通道下载异常: " + e3);
        }
    }

    return null;
}

/**
 * @name 酷狗音乐
 * @id kugou_official
 * @version 1.1.0
 * @author lee
 * @description 酷狗音乐官方源，采用手机端正版检索、精细哈希匹配与高清专辑封面获取。
 */

function search(title, artist, duration) {
    var keyword = (title + " " + (artist || "")).trim();
    var results = [];

    // 1. 优先使用酷狗移动端综合搜索接口 (高权重正版曲库，杜绝杂音与泛滥翻唱)
    try {
        var mobileUrl = "http://mobilecdn.kugou.com/api/v3/search/song?keyword=" + encodeURIComponent(keyword) + "&page=1&pagesize=15";
        var mobileResp = http.get(mobileUrl, {
            "User-Agent": "Mozilla/5.0 (Android; Mobile)"
        });
        if (mobileResp) {
            var data = JSON.parse(mobileResp);
            var list = (data && data.data && data.data.info) || [];
            for (var i = 0; i < list.length; i++) {
                var item = list[i];
                var sName = item.songname || item.songname_original || "";
                var aName = item.singername || "";
                var dur = parseInt(item.duration || 0);
                if (item.hash) {
                    results.push({
                        id: item.hash + "|" + dur + "|" + encodeURIComponent(sName) + "|" + encodeURIComponent(aName),
                        title: sName,
                        artist: aName,
                        duration: dur
                    });
                }
            }
        }
    } catch (e) {
        console.error("酷狗移动端搜索异常: " + e);
    }

    // 2. 备用降级：若移动端未返回，尝试旧版接口兜底
    if (results.length === 0) {
        try {
            var backupUrl = "http://songsearch.kugou.com/song_search_v2?keyword=" + encodeURIComponent(keyword) + "&page=1&pagesize=10&filter=0&bitrate=0&isfreeze=0&feedback=0";
            var backupResp = http.get(backupUrl, {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
            });
            if (backupResp) {
                var bData = JSON.parse(backupResp);
                var bList = (bData && bData.data && bData.data.lists) || [];
                for (var j = 0; j < bList.length; j++) {
                    var bItem = bList[j];
                    var bsName = bItem.SongName || bItem.AudioName || "";
                    var baName = bItem.SingerName || "";
                    var bDur = parseInt(bItem.Duration || 0);
                    if (bItem.FileHash) {
                        results.push({
                            id: bItem.FileHash + "|" + bDur + "|" + encodeURIComponent(bsName) + "|" + encodeURIComponent(baName),
                            title: bsName,
                            artist: baName,
                            duration: bDur
                        });
                    }
                }
            }
        } catch (e2) {
            console.error("酷狗兜底搜索异常: " + e2);
        }
    }

    return results;
}

function getLyrics(id) {
    var parts = id.split("|");
    var hash = parts[0];
    var duration = parts.length > 1 ? parseInt(parts[1]) : 0;
    var title = parts.length > 2 ? decodeURIComponent(parts[2]) : "";
    var artist = parts.length > 3 ? decodeURIComponent(parts[3]) : "";

    var keyword = (title + " " + artist).trim();
    var searchUrl = "http://krcs.kugou.com/search?ver=1&man=yes&client=mobi&keyword=" + encodeURIComponent(keyword) + "&duration=" + (duration * 1000) + "&hash=" + hash;
    var searchResp = http.get(searchUrl, {
        "User-Agent": "Mozilla/5.0 (Android; Mobile)"
    });
    if (!searchResp) return null;

    try {
        var searchData = JSON.parse(searchResp);
        var candidates = searchData.candidates || [];
        if (candidates.length === 0) return null;

        // 优先筛选官方推荐歌词或评分高且曲名匹配的歌词
        var cand = candidates[0];
        for (var i = 0; i < candidates.length; i++) {
            var c = candidates[i];
            if (c.product_from === "官方推荐歌词" || (c.score && c.score >= 50)) {
                cand = c;
                break;
            }
        }

        var downUrl = "http://krcs.kugou.com/download?ver=1&client=mobi&id=" + cand.id + "&accesskey=" + cand.accesskey + "&fmt=lrc&charset=utf8";
        var downResp = http.get(downUrl, {
            "User-Agent": "Mozilla/5.0 (Android; Mobile)"
        });
        if (!downResp) return null;

        var downData = JSON.parse(downResp);
        var base64Lrc = downData.content || "";
        if (!base64Lrc) return null;

        var lrc = crypto.base64Decode(base64Lrc);

        // 获取高清专辑封面
        var cover = null;
        try {
            var infoUrl = "http://m.kugou.com/app/i/getSongInfo.php?cmd=playInfo&hash=" + hash;
            var infoResp = http.get(infoUrl, {
                "User-Agent": "Mozilla/5.0 (Android; Mobile)"
            });
            if (infoResp) {
                var infoData = JSON.parse(infoResp);
                var rawCover = infoData.album_img || infoData.imgUrl || "";
                if (rawCover) {
                    cover = rawCover.replace("{size}", "400");
                }
            }
        } catch (_) {}

        return {
            lrc: lrc,
            cover: cover
        };
    } catch (e) {
        console.error("酷狗歌词解析异常: " + e);
        return null;
    }
}

/**
 * @name 酷我音乐
 * @id kuwo_official
 * @version 1.0.1
 * @author lee
 * @description 酷我音乐官方极速直连源，支持毫秒级时间轴与高清封面。
 */

function search(title, artist, duration) {
    var keyword = (title + " " + artist).trim();
    var url = "http://www.kuwo.cn/search/searchMusicBykeyWord?vipver=1&client=kt&ft=music&cluster=0&strategy=2012&encoding=utf8&rformat=json&mobi=1&issubtitle=1&pn=0&rn=5&all=" + encodeURIComponent(keyword);
    var resp = http.get(url, {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
    });
    if (!resp) return [];

    try {
        var data = JSON.parse(resp);
        // 酷我 searchMusicBykeyWord 返回顶层 abslist；兼容旧版 data.data.list
        var list = data.abslist || (data.data && data.data.list) || (data.data && data.data.abslist) || [];
        var results = [];
        for (var i = 0; i < list.length; i++) {
            var item = list[i];
            var musicId = String(item.MUSICRID || item.DC_TARGETID || "").replace("MUSIC_", "");
            if (!musicId) continue;
            results.push({
                id: musicId,
                title: item.NAME || item.SONGNAME || "",
                artist: item.ARTIST || "",
                duration: parseInt(item.DURATION || 0)
            });
        }
        return results;
    } catch (e) {
        console.error("酷我搜索解析异常: " + e);
        return [];
    }
}

function getLyrics(id) {
    var headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Referer": "https://www.kuwo.cn/"
    };
    // 旧 m.kuwo.cn/songinfoandlrc 已失效；改用 openapi
    var url = "http://www.kuwo.cn/openapi/v1/www/lyric/getlyric?musicId=" + id;
    var resp = http.get(url, headers);
    if (!resp) return null;

    try {
        var data = JSON.parse(resp);
        var lrclist = (data && data.data && data.data.lrclist) || [];
        if (!lrclist.length) return null;

        var cover = null;
        var infoResp = http.get("https://wapi.kuwo.cn/api/www/music/musicInfo?mid=" + id + "&httpsStatus=1", headers);
        if (infoResp) {
            try {
                var info = JSON.parse(infoResp);
                cover = (info && info.data && info.data.pic) || null;
            } catch (_) {}
        }

        var lrcLines = [];
        for (var i = 0; i < lrclist.length; i++) {
            var item = lrclist[i];
            var totalSec = parseFloat(item.time || 0);
            var min = Math.floor(totalSec / 60);
            var sec = Math.floor(totalSec % 60);
            var ms = Math.floor((totalSec % 1) * 100);
            var minStr = (min < 10 ? "0" : "") + min;
            var secStr = (sec < 10 ? "0" : "") + sec;
            var msStr = (ms < 10 ? "0" : "") + ms;
            lrcLines.push("[" + minStr + ":" + secStr + "." + msStr + "]" + (item.lineLyric || ""));
        }

        return {
            lrc: lrcLines.join("\n"),
            cover: cover
        };
    } catch (e) {
        console.error("酷我歌词解析异常: " + e);
        return null;
    }
}

/**
 * @name 网易云音乐
 * @id netease_official
 * @version 1.0.0
 * @author lee
 * @description 网易云音乐官方源，支持原生 YRC 逐字卡拉OK歌词与超清封面。
 */

function search(title, artist, duration) {
    var keyword = (title + " " + artist).trim();
    var url = "http://music.163.com/api/search/get/web?s=" + encodeURIComponent(keyword) + "&type=1&offset=0&total=true&limit=5";
    var resp = http.get(url, {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Referer": "http://music.163.com"
    });
    if (!resp) return [];

    try {
        var data = JSON.parse(resp);
        var songs = (data && data.result && data.result.songs) || [];
        var results = [];
        for (var i = 0; i < songs.length; i++) {
            var s = songs[i];
            var artistNames = [];
            if (s.artists) {
                for (var j = 0; j < s.artists.length; j++) {
                    artistNames.push(s.artists[j].name);
                }
            }
            results.push({
                id: String(s.id),
                title: s.name || "",
                artist: artistNames.join(" / "),
                duration: Math.round((s.dt || 0) / 1000)
            });
        }
        return results;
    } catch (e) {
        console.error("网易云搜索解析异常: " + e);
        return [];
    }
}

function getLyrics(id) {
    var lyricUrl = "http://music.163.com/api/song/lyric?os=pc&id=" + id + "&lv=-1&kv=-1&tv=-1&rv=1&yv=1";
    var lyricResp = http.get(lyricUrl, {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        "Referer": "http://music.163.com",
        "Cookie": "os=pc"
    });
    if (!lyricResp) return null;

    try {
        var lyricData = JSON.parse(lyricResp);
        // 优先使用逐字卡拉OK (yrc)，其次普通 lrc
        var lrc = (lyricData.yrc && lyricData.yrc.lyric) ||
                  (lyricData.klyric && lyricData.klyric.lyric) ||
                  (lyricData.lrc && lyricData.lrc.lyric) || "";

        if (!lrc) return null;

        // 获取封面
        var cover = null;
        var detailUrl = "http://music.163.com/api/song/detail/?id=" + id + "&ids=[" + id + "]";
        var detailResp = http.get(detailUrl, {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Referer": "http://music.163.com"
        });
        if (detailResp) {
            try {
                var detailData = JSON.parse(detailResp);
                if (detailData.songs && detailData.songs.length > 0 && detailData.songs[0].album) {
                    cover = detailData.songs[0].album.picUrl;
                }
            } catch (_) {}
        }

        return {
            lrc: lrc,
            cover: cover
        };
    } catch (e) {
        console.error("网易云歌词解析异常: " + e);
        return null;
    }
}

/**
 * @name QQ音乐
 * @id qqmusic_official
 * @version 1.0.1
 * @author lee
 * @description QQ音乐官方源，支持精准搜索匹配、歌词解码与高清专辑封面。
 */

function search(title, artist, duration) {
    var keyword = (title + " " + artist).trim();
    // client_search_cp 在部分网络环境返回 500；改用 H5 搜索接口
    var url = "https://c.y.qq.com/soso/fcgi-bin/search_for_qq_cp?g_tk=5381&uin=0&format=json&inCharset=utf-8&outCharset=utf-8&notice=0&platform=h5&needNewCode=1&w="
        + encodeURIComponent(keyword)
        + "&zhidaqu=1&catZhida=1&t=0&flag=1&ie=utf-8&sem=1&aggr=0&perpage=5&n=5&p=1&remoteplace=txt.mqq.all";
    var resp = http.get(url, {
        "User-Agent": "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36",
        "Referer": "https://i.y.qq.com/"
    });
    if (!resp) return [];

    try {
        var data = JSON.parse(resp);
        var list = (data && data.data && data.data.song && data.data.song.list) || [];
        var results = [];
        for (var i = 0; i < list.length; i++) {
            var item = list[i];
            if (!item.songmid) continue;
            var singers = [];
            if (item.singer) {
                for (var j = 0; j < item.singer.length; j++) {
                    singers.push(item.singer[j].name);
                }
            }
            results.push({
                id: item.songmid + "|" + (item.albummid || ""),
                title: item.songname || "",
                artist: singers.join(" / "),
                duration: parseInt(item.interval || 0)
            });
        }
        return results;
    } catch (e) {
        console.error("QQ音乐搜索解析异常: " + e);
        return [];
    }
}

function getLyrics(id) {
    var parts = id.split("|");
    var songmid = parts[0];
    var albummid = parts.length > 1 ? parts[1] : "";

    var url = "https://c.y.qq.com/lyric/fcgi-bin/fcg_query_lyric_new.fcg?songmid=" + songmid + "&format=json&nobase64=1";
    var resp = http.get(url, {
        "User-Agent": "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36",
        "Referer": "https://y.qq.com/"
    });
    if (!resp) return null;

    try {
        var data = JSON.parse(resp);
        var rawLyric = data.lyric || "";
        if (!rawLyric) return null;

        var lrc = rawLyric;
        // 若依然为 base64 则解码
        if (rawLyric.indexOf("[") === -1 && /^[A-Za-z0-9+/=\r\n]+$/.test(rawLyric)) {
            lrc = crypto.base64Decode(rawLyric);
        }

        var cover = null;
        if (albummid) {
            cover = "https://y.gtimg.cn/music/photo_new/T002R300x300M000" + albummid + ".jpg";
        }

        return {
            lrc: lrc,
            cover: cover
        };
    } catch (e) {
